from pathlib import Path
import json,html
p=Path(__file__).resolve().parent;d=p/'representative-v7-left';index=json.loads((d/'index.json').read_text())
rows=[]
for state,m in index['clips'].items():
 rows.append('<tr><td>'+state+'</td><td>'+str(m['frames'])+'</td><td>30</td><td>'+str(m['frames']/30)+' s</td><td>'+('loop' if m['loop'] else 'hold final' if m['hold'] else 'one-shot, return pose')+'</td></tr>')
contacts=[]
for state in index['clips']:
 contacts.append('<section><h2>'+state.title()+'</h2><img class="contact" src="representative-v7-left/'+state+'-contact.jpg" alt="Eight chronological '+state+' poses"><p><a href="../../../animations/sprites/enemies/animations/SS_hallMirror_'+state+'.png">Source sheet</a> · <a href="../../../game/assets/sprites/enemy-clips/hall-mirror/'+state+'.webp">Runtime atlas</a> · <a href="representative-v7-left/'+state+'-preview.webp">Animated WebP preview</a></p></section>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hall Mirror — four actions at 30 fps</title><style>body{font:16px/1.5 system-ui;background:#20212b;color:#eceaf4;max-width:1150px;margin:24px auto;padding:20px}a{color:#bdcfff}h1{line-height:1.1}.layout{display:flex;gap:32px;flex-wrap:wrap}.player{width:384px;max-width:100%}canvas{width:100%;height:auto;background:repeating-conic-gradient(#292a35 0% 25%,#353643 0% 50%) 0/24px 24px;border:1px solid #74758a}.info{flex:1;min-width:290px}button,select,input{font:inherit;padding:8px;margin:5px}input[type=range]{width:90%;padding:0}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #5c5d6b;text-align:left}.contact{width:100%;height:auto}.notice{border-left:3px solid #b1a3e8;padding:14px;background:#292b38}section{margin-top:32px}small{color:#bfc0d2}</style></head><body><p><a href="animation-gallery.html">Complete enemy/action matrix and earlier diagnostic</a></p><h1>Hall Mirror: four actions at 30 fps</h1><p class="notice">Corrected character-specific source-art rig; full-speed intended-size visual review pending. The authentic gold frame stays fixed; the reflection's head, body and palm move independently. Opaque pupils are covered by moving eyelids; explicit character mattes replace signed background subtraction. This is layered 2D animation, not fully redrawn frames or AI video. Browser opening was denied by URL policy and was not retried; all source/atlas/animated-WebP frames were decoded and checked.</p><div class="layout"><div class="player"><canvas width="256" height="384" aria-label="Hall Mirror animation preview"></canvas><label>Action <select id="action"><option>idle</option><option>attack</option><option>hurt</option><option>defeat</option></select></label><p><button id="play">Pause</button><button id="replay">Replay</button><button id="step">Next frame</button></p><input id="scrub" type="range" min="0" max="59" value="0" aria-label="Frame"><p id="status" aria-live="polite">Loading local atlases…</p></div><div class="info"><h2>Action design</h2><p><b>Idle:</b> soft breathing, a short blink and a traveling glass glint. Loops without moving the stand.</p><p><b>Attack:</b> withdraws in anticipation, lifts its palm for a premature greeting, waves twice and recovers.</p><p><b>Hurt:</b> recoils, shuts its eyes, tucks the hand inward and regains its resting pose.</p><p><b>Defeat:</b> offers a last goodbye, bows and sinks out of the glass. The empty mirror remains, with a nonlooping final hold.</p><p>No separate cast is required in the approved Hall Mirror matrix: its distinctive reflection gesture is in attack. No gameplay intent mapping was changed.</p><table><thead><tr><th>Action</th><th>Frames</th><th>FPS</th><th>Duration</th><th>Finish</th></tr></thead><tbody>__ROWS__</tbody></table><p>Source cells: 512 × 768. Runtime cells: 256 × 384. Nine columns; chronological row-major order. Shared anchor [128,372], unit 360. All atlases use the existing per-enemy metadata schema.</p><p><a href="representative-v7-left/validation.json">Validation results</a> · <a href="published-clips.json">Exact saved paths and hashes</a> · <a href="../../../game/assets/sprites/enemy-clips/hall-mirror/index.json">Final metadata</a></p><p><small>The HTML clock advances at 1000/30 ms per frame. One-shots stop at their last pose for inspection; Replay restarts them. Animated WebP previews use 33/34 ms frame durations totaling each exact clip duration. Defeat never automatically returns to idle.</small></p></div></div>__CONTACTS__<script>const clips=__INDEX__.clips,images={},canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),select=document.querySelector('#action'),scrub=document.querySelector('#scrub'),status=document.querySelector('#status'),play=document.querySelector('#play');let state='idle',frame=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,origin=null;function draw(){const m=clips[state],im=images[state];if(!im||!im.complete||!im.naturalWidth)return;ctx.clearRect(0,0,256,384);ctx.drawImage(im,frame%m.cols*m.fw,Math.floor(frame/m.cols)*m.fh,m.fw,m.fh,0,0,256,384);scrub.max=m.frames-1;scrub.value=frame;status.textContent=state+' — frame '+(frame+1)+' / '+m.frames+' · 30 fps'+(!playing?' · paused/held':'');play.textContent=playing?'Pause':'Play';}function restart(){state=select.value;frame=0;origin=null;playing=true;draw()}select.onchange=restart;document.querySelector('#replay').onclick=restart;play.onclick=()=>{if(frame===clips[state].frames-1&&!clips[state].loop)frame=0;playing=!playing;origin=null;draw()};document.querySelector('#step').onclick=()=>{playing=false;origin=null;frame=Math.min(frame+1,clips[state].frames-1);draw()};scrub.oninput=()=>{playing=false;origin=null;frame=Number(scrub.value);draw()};function tick(t){if(playing){if(origin===null)origin=t-frame*1000/30;const m=clips[state],raw=Math.floor((t-origin)*30/1000);let next;if(m.loop)next=raw%m.frames;else{next=Math.min(raw,m.frames-1);if(raw>=m.frames){playing=false;origin=null}}if(next!==frame){frame=next;draw()}else if(!playing)draw()}requestAnimationFrame(tick)}for(const name of Object.keys(clips)){const im=new Image();im.onload=draw;im.onerror=()=>{status.textContent='Unable to load '+name+' atlas'};im.src='../../../game/assets/sprites/enemy-clips/hall-mirror/'+clips[name].file;images[name]=im}requestAnimationFrame(tick);</script></body></html>'''
page=page.replace('__ROWS__',''.join(rows)).replace('__CONTACTS__',''.join(contacts)).replace('__INDEX__',json.dumps(index))
(p/'hall-mirror-preview.html').write_text(page,encoding='utf-8')
print('Saved Hall Mirror all-state preview')
